func TestUpsertBatch_PopulatesVolumePurchasingLocationsTable(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "test-001"}`),
		json.RawMessage(`{"id": "test-002"}`),
		json.RawMessage(`{"id": "test-003"}`),
	}
	if _, _, err := s.UpsertBatch("volume_purchasing_locations", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}

	db := s.DB()

	var generic int
	if err := db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, "volume_purchasing_locations").Scan(&generic); err != nil {
		t.Fatalf("count resources: %v", err)
	}
	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "volume_purchasing_locations")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count volume_purchasing_locations: %v", err)
	}
	if typed != len(items) {
		t.Fatalf("volume_purchasing_locations count = %d, want %d (typed table not populated by UpsertBatch)", typed, len(items))
	}
}

func TestSearchVolumePurchasingLocationsQuotesFTSQuerySyntax(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "typed-ip", "name": "10.0.0.1"}`),
		json.RawMessage(`{"id": "typed-host", "name": "host.example.com"}`),
		json.RawMessage(`{"id": "typed-multi", "name": "error with extra words before timeout"}`),
	}
	if stored, failed, err := s.UpsertBatch("volume_purchasing_locations", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	} else if failed != 0 || stored != len(items) {
		t.Fatalf("UpsertBatch stored=%d failed=%d, want stored=%d failed=0", stored, failed, len(items))
	}

	for _, query := range []string{
		"10.0.0.1",
		"host.example.com",
		"error timeout",
	} {
		results, err := s.SearchVolumePurchasingLocations(query, 10)
		if err != nil {
			t.Fatalf("SearchVolumePurchasingLocations(%q): %v", query, err)
		}
		if len(results) == 0 {
			t.Fatalf("SearchVolumePurchasingLocations(%q) returned no results", query)
		}
	}
}

